, NULL, NULL, 'en', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1016/j.apmr.2008.07.019', '19236980', NULL, NULL, NULL, 'https://doi.org/10.1016/j.apmr.2008.07.019', '2026-09-18', NULL, NULL, 1, 'clinical', 'US', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'crossref', NULL, 1, NULL, '271-278', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'high_control', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
