L, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1080/10400435.1997.10132293', '10168021', NULL, NULL, NULL, 'https://doi.org/10.1080/10400435.1997.10132293', '2026-09-18', NULL, NULL, 1, 'clinical', 'US', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'crossref', NULL, 1, NULL, '22-33', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'high_control', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-01002', NULL, NULL, 0, NULL, NULL, 0, NULL, 2009, NULL, 'Evaluation of Wheelchair Users'' Perceived Sidewalk and Ramp Slope: Effort and Accessibility', NULL, NULL, NULL, 'en', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://trid.trb.org/View/921388', '2026-09-18', NULL, NULL, 1, 'clinical', 'US', NULL, NULL, NULL, 'COMPLETE', 'UNVERIFIED', 'NO-MATCH', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:11', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, 1, NULL, '145-158', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CORRECTED', '2026-09-18 verification_status CORRECTED (I4 CAUGHT A GRADING ERROR AND THE CHECK IS RIGHT. I4 asserts VERIFIED is reachable only by a method that OBTAINS THE ARTEFACT, and this row paired VERIFIED with verification_method=corroborated-not-retrieved, which by its own name does not. The article was never obtained: what was retrieved is the TRID/TRB bibliographic record and its verbatim abstract (HTTP 200, 50825 bytes persisted). I graded existence-and-identity as VERIFIED and the column means something stricter. UNVERIFIED is the true value and the research contract says so in as many words. It also makes the row agree with everything else this batch asserts about the source: extraction skim, status preliminary, determination gate 1 open, GAP-016 owed.). Replaced text was: ''VERIFIED'' || 2026-09-18 doi_resolution_outcome CORRECTED (C04 asserts a COMPLETE row either carries a doi, is co1-verified, or has NO-MATCH on record. This source genuinely HAS no DOI -- Journal of Architectural and Planning Research 26(2):145-158, ISSN 0738-0895, 2009, none assigned. NO-MATCH is the accurate outcome of the R10 ladder rather than a token to satisfy a gate: the DOI rung returned nothing because there is nothing to return, and the record was reached by title through TRID instead. Left NULL on first write, which is the state C04 exists to catch.). Replaced text was: None || 2026-09-18 verification_disposition CORRECTED (VERIFICATION IS NOT FINISHED ON THIS SOURCE AND THE ROW SHOULD NOT SAY IT IS. D-0157 states the disposition as a judgement -- verification is finished or it did not happen. Here it did not happen: the TRID/TRB record and its verbatim abstract were retrieved, the ARTICLE was not, and GAP-016 (P1) owes the full read with four named questions the abstract cannot answer. CLOSED arrived as add-source default at a moment when the row still read VERIFIED; correcting the status to UNVERIFIED left the disposition asserting a finished verification behind it, which I3 and I3b caught -- CLOSED with no closure reason and a single attempt. The closure vocabulary confirms it: paywalled, print-only, access-denied-persistent, withdrawn, not-found-after-search, disputed-existence. NONE of them is true here. This article is not paywalled-after-effort; it simply has not been fetched.). Replaced text was: ''CLOSED''', NULL, NULL, NULL, NULL, 'high_control', 'captured', 'deferred', NULL, NULL, NULL, NULL, 'OPEN', 'corroborated-not-retrieved', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-016', 'EG', 'P1', 'OPEN', NULL, NULL, 'READ VREDENBURGH ET AL. 2009 (REF-01002) IN FULL. IT IS THE FIRST ANCHORING-TIER STATED MAXIMUM THIS PARAMETER HAS HAD, AND IT IS HELD AT SKIM GRADE. The TRID/TRB record and its verbatim abstract were retrieved and persisted this batch (HTTP 200, 50825 bytes) and give: Results suggest that for a transit distance of up to 20 feet, a ramp should not exceed a maximum cross slope of 5% or a maximum running slope of 7%. THE ARTICLE ITSELF WAS NOT RETRIEVED. Journal of Architectural and Planning Research 26(2):145-158, ISSN 0738-0895, NO DOI -- which is why six batches of DOI-keyed searching never met it and why it sat unread inside REF-00977 reference list. WHAT THE FULL READ MUST SETTLE, none of which the abstract answers: (1) the participant count and composition -- the record says users of manual AND motorised wheelchairs and states no n, so the population match is graded PARTIAL on an unknown denominator; (2) the slope set actually tested, since 7% may be a recommendation or merely the highest slope at which perceived effort did not degrade, and those are different claims; (3) whether the 20-foot transit distance is a tested bound or an assumption; (4) whether disabled people shaped the study beyond serving as subjects, which under D-0178 is the difference between T1 and Co-1. ON RESOLUTION: promote extraction 45 from skim/preliminary, resolve determination gate 1, and re-determine parameter 3 x MOB -- or record that the abstract overstated. UNTIL THEN THE FIGURE DOES NOT MOVE. Specification 8 stands at 5% and is SAFE rather than correct: 7% is LOOSER, the parameter direction is lower_is_better, so the standing value errs conservative while its tier_basis (T4-6-only-threshold, rests_on_proxy_inference=1) describes the wrong evidence. Batch 15 refused to claim Co-1 for REF-01001 on an ambiguous abstract and the full text vindicated the refusal; this is the same discipline one column along. TRID also lists the publisher as Elsevier Science, which is wrong for this journal -- do not propagate it; the publisher field was left unwritten for that reason.', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-017', 'SW', 'P2', 'OPEN', NULL, NULL, 'log-mining COULD NOT EXPRESS A MINING PASS THAT RAN AND FOUND NOTHING, AND NEVER CLEARED A DEFERRAL IT DISCHARGED -- BOTH FIXED THIS BATCH, AND THE GAP RECORDS WHAT IS STILL OWED. Measured on 2026-09-18: (a) the writer refused an empty connections list unless --deferred-reason was given, but R6 says deferred_reason means DELIBERATELY NOT SEARCHED, so the only expressible record of REF-00984 executed zero-yield pass over 38 deposited references was a false one; (b) citation_mining.notes existed with NO WRITER AT ALL, which is why every substantive mining note in this table before today sits in deferred_reason; (c) the writer set backward=1, status=mined and connections on a row while leaving its deferred_reason intact -- observed live this session on REF-00977, whose row simultaneously said mined, produced REF-01002 and BACKWARD PASS DEFERRED. (c) is the RAP-F61/F69/F70 shape the citation-miner skill already records: a register that says a finished pass is owed is how a session re-queues finished work. FIXED FORWARD: --notes added; --notes and --deferred-reason made mutually exclusive; a pass that runs now DISCHARGES a standing deferral and CARRIES its text into notes rather than destroying it (2026-09-16 retire-in-place). STILL OWED, and this gap is for these: (1) NOTHING GATES THE CONTRADICTION -- no registered check asserts that a row with backward=1 or forward=1 and a non-empty connections set has no deferred_reason, so the state this batch found can recur silently; (2) the SEVEN rows on this slug still carrying deferrals were left untouched deliberately, because their passes genuinely have not run and rewriting them would destroy the record of what was owed; (3) the same conflation may exist in other writers that carry a deferred_reason column -- unswept, and rule 4 says a sweep is what closes it.', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-018', 'RP', 'P2', 'OPEN', NULL, NULL, 'THE PROJECT RANKED ITS OWN MINING TARGETS AND GOT THEM EXACTLY BACKWARDS, TWICE, AND THE PREDICTOR THAT WOULD HAVE WORKED IS CHEAP. Batch 15 deferred three anchors with explicit rankings: REF-00984 (a systematic review of wheelchair SKILLS TESTS) HIGHEST-VALUE TARGET, REF-00985 (a biomechanics paper) LOWEST expected yield. Measured this batch against the same ramp/slope/gradient screen: REF-00984 yielded 0 of 38, REF-00985 yielded 23 of 46 and produced both of the batch anchoring-tier admissions. My own pre-registered priors were wrong in the same two places and in one further way -- I predicted REF-00984 would yield test-apparatus numbers needing a guard, and it yielded no slope references at all. THE REGULARITY IS DERIVABLE AND NEITHER SESSION DERIVED IT: a paper cites the literature of ITS OWN INDEPENDENT VARIABLE. REF-00985 measures propulsion effort, so it cites propulsion-on-slopes work; REF-00984 reviews measurement INSTRUMENTS, so it cites reliability, scoring and construct validity. Topical proximity of the ANCHOR to the slug predicted nothing; what the anchor MEASURES predicted everything. WHAT IS OWED: this is a hypothesis from two observations and must not become doctrine on that basis. Test it prospectively -- record a predicted yield for each deferred anchor BEFORE the pass, from what the anchor measures rather than what it is about, and check the prediction after. If it holds over a further three or four passes it belongs in the citation-miner skill relevance filter, which today screens DISCOVERIES for relevance and says nothing about ranking ANCHORS. A second, cheaper finding rides along and should be tested with it: 3 of the 3 best finds this batch (REF-01002 admitted, plus candidates 102 and 103) carry NO DOI in the deposit, so a DOI-keyed screen would have missed all three.', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-019', 'SW', 'P1', 'OPEN', NULL, NULL, 'assess_cell CANNOT EMIT AN ANCHORED provisional CELL: IT REACHES THE STATE AND THEN ITS OWN PYDANTIC GATE REFUSES IT, AS A TRACEBACK. Measured 2026-09-18 on a throwaway copy with parameter 3 x MOB after REF-01002 T1 claim was extracted. determine() returns state=provisional, tier_basis=T1, value_max=7.0, unit=%, rests_on_proxy_inference=0, confidence=None; validate_with_models then raises ValidationError -- State provisional requires confidence_flag (name evidence dimensions present and absent) -- and the process dies at assess_cell.py:1923 having written nothing, with no --emit-sql file. THE ASYMMETRY IS THE DEFECT: the PROXY branch builds a ProvisionalConfidenceFlag (specs 4-8 all carry populated dimensions), the ANCHORED branch does not, and nothing in between notices that provisional is reachable down both. It was unreachable until this batch because no anchoring-tier CLAIM had ever existed for a determined parameter. TWO THINGS THAT MUST NOT BE CONFLATED WITH IT. (1) This is a crash, not a refusal-by-design: the no-re-determination refusal on idx_spec_row_identity prints a sentence and exits 1 deliberately; this prints a stack trace naming a pydantic model. (2) FIXING IT IS NOT A DEFECT FIX. Deciding which dimensions an anchored-provisional cell has PRESENT and ABSENT is a statement about what the confidence flag means, and the engine own comments twice refuse to invent doctrine inside a defect fix. It needs a ruling or a DR. WHAT THE ENGINE WOULD HAVE WRITTEN IS THE SECOND HALF OF THIS GAP AND IS ARGUABLY MORE URGENT: a single T1 claim DISPLACED the whole regulatory stratum -- governing and supporting both came back None, value moved 5% to 7%, and rests_on_proxy_inference cleared -- rather than composing with it most-accommodatingly under the lower_is_better direction the parameter carries. If that is the intended behaviour it should be stated somewhere; if it is not, it is a second defect sitting behind the first, and the first is currently hiding it.', '2026-09-18 20:13', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:13', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-020', 'AUDT', 'P1', 'OPEN', NULL, NULL, 'THE CORPUS NOW HAS ZERO LIVE DETERMINATIONS, AND K01/K02 PASS BY HAVING NOTHING TO EXAMINE. Batch 16 retired specification 8 in place because K02 (blocking) requires a LIVE determination to account for every extraction of its parameter and this batch added five it did not hold; the engine could not recompute the cell (GAP-019). test_db_integrity then went 74/74 -- and K01 and K02 appear in its own PASSED HAVING EXAMINED NOTHING list, which grew from 19 to 22. THAT IS CLAUDE.md SECTION 5(a) VERBATIM, the failure mode this repository has produced four separate times: a gate that passes having examined nothing. IT IS RECORDED HERE RATHER THAN BANKED AS A GREEN RUN. The retirement is defensible -- a live cell omitting new evidence attests a subset while reading as the whole, which is K02 own stated reason, and the alternative was writing 7% onto a skim extraction from an abstract in a third-party index. But three things follow that a reader must not have to derive. (1) Nothing in the book now states a ramp gradient; specification 8 remains readable as history at 5% / 1:20 and is NOT live. (2) The green integrity run says less than it did yesterday, and comparing 74/74 today against 74/74 before this batch would be a false equivalence -- the denominator of examined checks fell. (3) This is the SECOND time in three batches that the determination surface emptied: batch 15 code review caught spec 7 retired and never re-determined, and fixed it by determining spec 8. It cannot be fixed the same way here, because the engine refuses. CLOSING CONDITION: GAP-016 full read, then GAP-019 engine ruling, then re-determine. Until both, parameter 3 x MOB is undetermined and determination gate 1 stays open.', '2026-09-18 20:13', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:13', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-021', 'SW', 'P1', 'OPEN', NULL, NULL, 'citation_mining.backward AND .forward ARE SET TO 1 ON A PASS THAT WAS DEFERRED, SO THE DIRECTION FLAGS DO NOT MEAN THE PASS RAN -- AND citation_mining_completeness READS THEM AS IF THEY DID. log_mining executes UPDATE citation_mining SET <direction>=1 UNCONDITIONALLY and only afterwards writes deferred_reason, so every deferral leaves a flag asserting the direction was mined. Derive it, never quote it: select count(*) from citation_mining where (backward=1 or forward=1) and deferred_reason is not null -- measured 2026-09-18 at 10 of 23 rows, i.e. EVERY deferred row. CONSEQUENCE, AND IT IS A LIVE OVERSTATEMENT ON A GREEN CHECK: citation_mining_completeness prints 10/10 T1-2 sources mined, 100.0% repo-wide, counting row presence. On accessible-circulation-geometry the number of sources whose BACKWARD pass has actually been executed is 3 of 13 -- REF-00977, REF-00984, REF-00985 -- and batch 16 is what executed all three. The other ten are deferrals wearing a mined flag. THE TRUTH IS RECOVERABLE TODAY only from evidence_sources.citation_mining_status (mined vs deferred) and, since this batch, from whether notes or deferred_reason is populated. That is two columns disagreeing with a third about one fact, which is rule 5. A THIRD FACE OF THE SAME DEFECT, found while deriving the above: deferred_reason is ONE column serving BOTH directions. A row that defers backward and executes forward cannot say so, and discharging a deferral raised for one direction clears it for both -- which this batch did to REF-00977, whose forward flag was set by batch 15 and whose current row can no longer state what that forward pass was. WHAT TO FIX, IN ORDER: (1) do not set the direction flag when the pass is deferred, or split the columns into attempted and executed; (2) make citation_mining_completeness read execution rather than presence, and re-derive its percentage; (3) key the deferral per direction. (1) and (2) must land together -- fixing the flag alone would silently move the completeness figure without anyone seeing why. RELATED BUT DISTINCT: GAP-017 (notes had no writer, deferrals never discharged), GAP-015 (is the obligation per source or per source-slug).', '2026-09-18 20:14', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:14', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-022', 'SW', 'P1', 'OPEN', NULL, NULL, 'GAP-021 IS PARTLY SUPERSEDED BY THE OWNER RULING OF 2026-09-18 AND THIS ROW CARRIES THE CORRECTED VERSION. Ruling, verbatim: executed is mined / deferred is okay so long as it runs eventually (references/project-standards.md, 2026-09-18). WHAT IT OVERTURNS IN GAP-021: that gap proposed splitting citation_mining.backward and .forward into attempted-versus-executed columns. THAT IS REFUSED. The execution signal already exists -- evidence_sources.citation_mining_status, mined versus deferred, live and correctly derived by log_mining -- and building a second home for it is rule 5. The direction flags say a pass was LOGGED; the status says whether it RAN; read both. GAP-021 also framed ten deferrals as a defect, and they are not: depth-1 (citation-miner section 6) forbids mining an anchor admitted in the same pass, so deferring is the designed behaviour and batch 16 three new deferrals are correct. WHAT SURVIVES GAP-021 INTACT: citation_mining_completeness counts ROW PRESENCE, so it reports deferrals as mined. Measured 2026-09-18 it printed 10/10 T1-2 sources mined, 100.0% repo-wide while backward had actually been EXECUTED on 3 of 13 sources on accessible-circulation-geometry. Under the ruling that check is simply reading the wrong column and must read citation_mining_status. Until it does, its percentage is an overstatement and must be flagged wherever quoted. WHAT THE RULING NEWLY OPENS, AND IT IS THE HALF WITH NO MECHANISM: so long as it runs eventually is an OBLIGATION, and nothing here enforces or even measures it. No ageing on a deferred row, no backlog count, no check that fails on an undischarged deferral. The register today holds deferrals from batch 08 beside batch 16 and cannot tell them apart by age. A deferral honoured next batch and one abandoned for six are the same row. THAT MEASURE IS THE OWED WORK: an age or a count on undischarged deferrals, landed together with the completeness fix so the percentage does not move silently. Derive both figures rather than quoting them; the ruling records the command.', '2026-09-18 20:15', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:15', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (66, 'accessible-circulation-geometry', 'HR', 'HR', 1, 'co1', 'intrinsic', 'HUPT Hrvatska udruga paraplegičara i tetraplegičara pristupačnost nagib rampe invalidska kolica preporuka', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:54', 'ZERO-YIELD, WELL-FORMED, GENUINE ABSENCE OF THE OBJECT SOUGHT -- not a query-shape failure and not an index failure (R14). HUPT exists, is a real DPO alliance of spinal-injury organisations, and its accessibility work is documented (monitoring public and tourist facility accessibility, working groups on legislative amendments). Its OWN publications page was then FETCHED rather than inferred from the result list: it lists three 2001 newsletters, a beaches guide for disabled people, an inclusive tourism guide, and rights/strategy documents. NO technical built-environment guidance and NO ramp gradient value in any of them. So the organisation is real, the search reached its own publication index, and the object sought is absent from it. Recorded as absence of a Co-1 THRESHOLD STATEMENT from this DPO, never as absence of Croatian Co-1 material generally.', 0, 'HR chosen because GAP-014 established HUPT facilitated REF-01001 as a named organisation -- participation, not co-production. If HUPT publishes accessibility guidance in its OWN voice that would be co-production and Co-1. Expect low-to-moderate yield with a real possibility of zero; a Croatian DPO may not publish technical guidance online, or may restate the national code, in which case it is T5/T6 and not Co-1.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (67, 'accessible-circulation-geometry', 'SE', 'SV', 1, 'co1', 'intrinsic', 'DHR Delaktighet Handlingskraft Rörelsefrihet tillgänglighet ramp lutning rullstol riktlinje procent', NULL, 'web', 'scoping', 'none', 9, 9, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:54', 'ZERO-YIELD FOR Co-1. DHR is confirmed as a real DPO and its accessibility advocacy is documented, but no DHR-AUTHORED technical gradient statement was reached. The result set DID surface a retrievable Swedish national accessibility guideline (Riktlinjer for tillganglighet, Riv hindren 2015, hosted on funktionsratt.se but authored by Myndigheten for delaktighet, a government agency) -- staged as a candidate, NOT admitted, because it is T5 national_fw and the threshold half of specification 8 already rests entirely on the T4-T6 stratum; another regulatory source cannot close GAP-002. A 1:12 / 8.3 per cent figure appeared in the SEARCH-ENGINE SUMMARY and is DELIBERATELY NOT RECORDED anywhere: it is a model-generated synthesis with no retrieved document behind it, which is the CLAUDE.md section 5(c) shape exactly.', 0, 'Second Co-1 route in a language not yet run on this parameter (batches 09-12 covered EN, DE, FR, NL, ES, JA). DHR is a Swedish DPO of people with reduced mobility. Expect either a DPO-authored accessibility guideline stating a gradient -- which would be Co-1 and would bear directly on GAP-002 -- or a restatement of the Swedish national rule, which would be T5 and would not.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (68, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.1080/17483107.2022.2111723 -- deposited reference list of REF-00977, screened for ramp/slope/gradient relevance', NULL, 'crossref', 'systematic', 'backward', 117, 117, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:54', 'PRIOR HELD, AND THE ONE HIT IT PREDICTED IS THE BATCH HEADLINE. Crossref deposits 117 reference entries, 81 carrying DOIs. The full text was NOT needed -- batch 15 deferred this pass on a Taylor & Francis 403, and the deposited reference list makes the same mining tractable without it, which is the reusable lesson. 6 of 117 pass the ramp/slope/gradient/barrier screen. Five are qualitative barrier or policy work, exactly as predicted. The sixth is Vredenburgh, Hedge, Zackowitz and Weiner 2009, Evaluation of wheelchair users perceived sidewalk and ramp slope: effort and accessibility -- carrying NO DOI in the deposit, so it is invisible to any DOI-keyed pass and had to be resolved by title. It is a wheelchair-user PERCEPTION experiment that states a maximum running slope, which is the exact object GAP-002 names as missing. Admitted under M3 exec so the admission sits with the pass that produced the corroborating anchors; recorded here as the discovery.', 0, 'M1. A review of the EFFECTS of inaccessible space. Expect its reference list to be dominated by qualitative barrier/participation work and survey instruments, not quantitative gradient thresholds. Expect 0-2 references stating a maximum acceptable gradient. Highest-probability yield is sidewalk/pathway running-slope and cross-slope work measured against wheelchair negotiation. Expect this to NARROW GAP-002 rather than close it.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (69, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.1191/0269215503cr633oa -- deposited reference list of REF-00984, screened for ramp/slope/gradient relevance', NULL, 'crossref', 'systematic', 'backward', 38, 38, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:54', 'ZERO-YIELD, AND IT FALSIFIES BOTH BATCH 15 AND MY OWN PRIOR -- in opposite directions, which is why it is worth the row. Crossref deposits 38 reference entries, 28 carrying DOIs. ZERO of 38 titles match the ramp/slope/incline/gradient screen at all. Batch 15 was wrong that this was the likeliest place a stated gradient exists. I was wrong too, but one layer further in: I predicted test-apparatus numbers that would need guarding against over-reading, and there are no slope references of ANY kind to over-read. A 2003 systematic review of wheelchair SKILLS TESTS cites the instrument-validation literature -- reliability, scoring, construct validity -- not the environmental-parameter literature. The deferral note that named it the highest-value target should be read as a hypothesis this pass refuted, and the correction belongs in the mining register so the next session does not re-queue it.', 0, 'M2. Batch 15 called this the HIGHEST-VALUE TARGET DELIBERATELY DEFERRED, reasoning that ascending slopes is among the most frequently included Wheelchair Skills Test tasks so its references are the likeliest place a stated gradient exists. My prior DISAGREES and is recorded before the read: the WST literature specifies the gradient of a TEST APPARATUS, which is an experimental condition and not a statement about what a ramp should be. Expect stated numbers (likely the WST-standard 1:12 and 1:8 incline pair) and expect them NOT to close GAP-002. A Kirby-et-al WST development paper is the expected top hit.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (70, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.3390/s23218659 -- deposited reference list of REF-00985, screened for ramp/slope/gradient relevance', NULL, 'crossref', 'systematic', 'backward', 46, 46, 3, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:55', 'MY PRIOR WAS WRONG BY THE WIDEST MARGIN IN THIS BATCH AND THE RECORD SHOULD SAY SO PLAINLY. I predicted 0 relevant references; 23 of 46 match the screen, and the ramp-slope seam this project has hunted since batch 08 sits inside them. Batch 15 ranked this anchor LOWEST of its three deferrals and REF-00984 HIGHEST; the ranking was exactly inverted. The reason was derivable beforehand and neither of us derived it: a biomechanics paper measuring propulsion effort cites the propulsion-on-slopes literature, whereas a systematic review of skills TESTS cites the instrument-validation literature. Three admitted: Sanford Story and Jones 1997 (entry 8), Chow et al. 2009 (entry 40), and Vredenburgh et al. 2009, the last reached via M1 and resolved by title because its deposit carries no DOI. Staged not admitted: Gagnon et al. 2014 pushrim-versus-slope and the 1989 portable-ramps appraisal. DEPTH-1 IS ENFORCED -- none of the three is mined in this pass.', 0, 'M3. An MDPI Sensors paper on fuzzy-logic MSD risk. Reference list expected to be biomechanics and signal processing. EXPECT 0 references stating a design threshold. Run because R2 owes it and because a null result on a named anchor is a completed unit of work, not because I expect yield.');
