INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (44, 'REF-00979', 'ramps of different slopes', 'EN', 'title; abstract (Objective)', 'examining the changes in kinematic and electromyographic characteristics of wheelchair propulsion over ramps of different slopes', NULL, '2026-09-18 19:56', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:56', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (45, 'REF-01002', 'running slope', 'EN', 'abstract', 'all of which specify requirements for ramp design, including their maximum running slope and cross slope', NULL, '2026-09-18 19:56', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:56', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (46, 'REF-01002', 'perceived effort', 'EN', 'abstract', 'the perceived effort (Borg scale) required to negotiate these ramps', NULL, '2026-09-18 19:56', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:56', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (70, 'REF-00979', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (70, 'REF-00980', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (70, 'REF-01002', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (96, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Pushrim biomechanical changes with progressive increases in slope during motorized treadmill manual wheelchair propulsion in individuals with spinal cord injury', '10.1682/JRRD.2013.07.0168', 'UNVERIFIED', 1, 0, 'HYPOTHESIS, NOT YET A FINDING (R15). Title alone says it measures pushrim load ACROSS a slope series -- the same dose-response shape as REF-00985 and REF-00986, which GAP-002 records as monotonic and therefore degenerate on their own. Highest-priority candidate of this batch: JRRD is open access, so the full text is reachable, and if it reports an inflection or plateau rather than a monotone rise it would CORROBORATE the 4-10 degree band of REF-00979 from an independent laboratory. Must be re-described from the source on resolution; do not let this description harden into a finding.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (97, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Coordination patterns of shoulder muscles during level-ground and incline wheelchair propulsion', '10.1682/JRRD.2012.06.0109', 'UNVERIFIED', 1, 0, 'HYPOTHESIS. Incline-versus-level shoulder coordination, JRRD and therefore open access. Likely a two-condition comparison rather than a slope series, which would make it weaker than the candidate above for threshold work -- stated as an expectation to be tested against the source, not as a screening conclusion.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (98, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Cardio-respiratory and subjective strains sustained by paraplegic subjects, when travelling on a cross slope in a manual wheelchair', '10.1016/j.apergo.2014.01.002', 'UNVERIFIED', 1, 0, 'HYPOTHESIS. CROSS SLOPE, NOT RUNNING SLOPE -- a different parameter from the one under determination, and staged rather than admitted for that reason. It matters anyway: REF-01002 states a 5% cross-slope maximum in the same sentence as its 7% running-slope maximum, so cross slope is a parameter this corpus will have to mint. Carries subjective strain alongside physiological measures, which is the acceptability half.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (99, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Stroke pattern and handrim biomechanics for level and uphill wheelchair propulsion at self-selected speeds', '10.1016/j.apmr.2006.09.017', 'UNVERIFIED', 1, 0, 'HYPOTHESIS. Uphill-versus-level handrim biomechanics. Staged, not admitted: a two-condition contrast supplies direction, which this parameter already has in abundance, and not a threshold, which is what it lacks.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (100, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Effect of backrest height on wheelchair propulsion biomechanics for level and uphill conditions', '10.1016/j.apmr.2011.10.023', 'UNVERIFIED', 1, 0, 'HYPOTHESIS. The independent variable is BACKREST HEIGHT, a chair property, with incline as a condition -- so it bears on the parameter only indirectly. Staged for completeness of the seam and ranked low.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (101, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Portable ramps for wheelchair users - An appraisal', '10.3109/03790798909166390', 'UNVERIFIED', 3, 0, 'HYPOTHESIS. A 1989 appraisal of PORTABLE ramps -- a class where gradient is dictated by a fixed threshold rise and an available run, so any stated limit would be strongly rise-conditioned. That is the same conditioning REF-01002 attaches to its 7% and REF-00996 gives as its mechanism. Age is not a disqualifier: an appraisal is a finding about devices in use, not a claim superseded by a later edition.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (102, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Evaluation of minimal mechanical effort during the ramp access of manual wheelchair', 'no DOI in the REF-00985 Crossref deposit; entry 12 of 46', 'UNVERIFIED', 1, 0, 'HYPOTHESIS, AND UNLOCATED. No DOI in the deposit, so it is invisible to every DOI-keyed pass -- the same blind spot that hid REF-01002 until it was resolved by title. Title suggests a MINIMISATION criterion over ramp access, which is nearer a threshold than a dose-response curve. Resolve by title before the next determination attempt.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (103, 70, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Effect of power-assistance on upper limb biomechanical and physiological variables during a 6-minute, manual wheelchair propulsion test', '10.1080/09638288.2021.1973586', 'UNVERIFIED', 2, 0, 'HYPOTHESIS. POWER-ASSISTED propulsion, so its device class is not manual_self_propelled and its findings do not transfer to the population the determination serves. Staged so the screen is auditable, ranked lowest of the M3 seam.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (104, 68, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'A systematic review of public transport accessibility for people using mobility devices', 'no DOI in the REF-00977 Crossref deposit; entry 32 of 117', 'UNVERIFIED', 2, 0, 'HYPOTHESIS. A second systematic review on the transport setting, where REF-00999 already records ramps remaining a barrier at bus ingress. Its reference list is a further pre-screened seam. Not admitted: a review of ACCESSIBILITY broadly is unlikely to state a gradient, and this batch has just measured how badly that guess can go in both directions.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (105, 68, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Accessibility facilitators and barriers affecting independent wheelchair transfers in the community', 'no DOI in the REF-00977 Crossref deposit; entry 69 of 117', 'UNVERIFIED', 3, 0, 'HYPOTHESIS. Facilitators and barriers in the community from wheelchair users own accounts -- a candidate for the ACCEPTABILITY half rather than the biomechanical half, and possibly for Co-1 depending on how it was produced. D-0178 applies: who produced it must be read from the methods, never inferred from the topic.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (106, 67, 'accessible-circulation-geometry', 'threshold-and-level-access', 'REHOME', 'Riktlinjer for tillganglighet - Riv hindren (2015), Myndigheten for delaktighet', 'https://funktionsratt.se/wp-content/uploads/2019/09/2015-5-riktlinjer-for-tillganglighet.pdf', 'UNVERIFIED', 5, 0, 'NOT ADMITTED ON PURPOSE, AND THE REASON IS THE POINT. This is a Swedish national accessibility guideline (T5 national_fw), retrievable and probably gradient-bearing. Specification 8 tier_basis already reads T4-6-only-threshold: the threshold half rests ENTIRELY on the regulatory stratum, and GAP-002 asks for an ANCHORING-tier threshold. One more T5 cannot close that gap and would pad the governing set while changing nothing. Staged so the lead is not lost. NOTE ALSO: it surfaced under a Co-1 query because a DPO hosts the PDF -- the host is not the author, and treating it as Co-1 would be D-0178 exactly.', NULL, 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:02');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00979', 'accessible-circulation-geometry', '23', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL);
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00980', 'accessible-circulation-geometry', '22', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL);
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01002', 'accessible-circulation-geometry', '24', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:55', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL);
INSERT INTO "determination_gates" ("gate_id", "parameter_id", "identity_code", "verdict", "trigger_ref_id", "trigger_tier", "trigger_evidence_type", "detail", "raised_at", "raised_by_session", "resolved_at", "resolved_by_session", "resolution_rationale") VALUES (1, 3, 'MOB', 'UNLINKED', 'REF-01002', 1, 'clinical', 'SPECIFICATION 8 FALSIFICATION CONDITION IS MET ON ITS FACE AND THE CELL DOES NOT REST ON THE SOURCE THAT MEETS IT. The condition reads: Overturned if a source states a value for this parameter at an anchoring tier (the cell then rests on that, not on a proxy). REF-01002 (Vredenburgh, Hedge, Zackowitz and Weiner 2009, T1 clinical/high_control) states one -- a maximum running slope of 7% for a transit distance up to 20 ft, from wheelchair users own Borg-scale perceived effort. Specification 8 tier_basis still reads T4-6-only-threshold+T1+CO1+T2-direction(proxy_inference) and rests_on_proxy_inference=1, so an anchoring-tier stated threshold now exists and is UNLINKED from the determination it bears on. THE CELL IS DELIBERATELY NOT RE-DETERMINED IN THIS BATCH, and that is the substance of this gate rather than an omission from it. Extraction 45 is extraction_method=skim, extraction_status=preliminary: the TRID/TRB record and its verbatim abstract were retrieved and persisted (HTTP 200, 50825 bytes), THE ARTICLE WAS NOT. Batch 15 set the precedent on REF-01001 and was right -- it declined to claim Co-1 from an ambiguous abstract and the full text proved the claim would have been false. Moving a determination onto an abstract in a bibliographic index is the same shape one column along. NOTE THE DIRECTION, because it is counter-intuitive and must not be lost: 7% is LOOSER than the 5% currently determined, and the parameter direction is lower_is_better, so the standing determination is SAFE and merely mis-warranted. Nothing here makes 5% wrong; it makes the account of WHY 5% into an account of the wrong evidence. RESOLUTION PATH: read Vredenburgh et al. full text (GAP-016) -- participant count, the slope set tested, and whether 7% is the authors recommendation or the highest slope at which perceived effort did not degrade. Then re-determine, or resolve this gate with the reason the abstract overstated.', '2026-09-18 20:03', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', NULL, NULL, NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (44, 'REF-01002', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'numerical', '20', 'ft', 'Results suggest that for a transit distance of up to 20 feet, a ramp should not exceed a maximum cross slope of 5% or a maximum running slope of 7%.', 'abstract', NULL, 'measurement_primary', 'REF-01002', NULL, 'participatory_spatial', 'mixed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'THE TRANSIT DISTANCE THE 7% RUNNING-SLOPE MAXIMUM IS CONDITIONED ON. Written as its own row because add-extraction refuses condition_on against prose -- you cannot be conditioned by a figure that does not exist as a row -- and the refusal is right: this project has already been bitten by a determination that dropped its qualifier. 20 ft is roughly 6.1 m. The source states nothing about ramps longer than this, so the 7% must never be read as an unconditioned maximum.', '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'condition', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (45, 'REF-01002', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'numerical', '7', '%', 'Results suggest that for a transit distance of up to 20 feet, a ramp should not exceed a maximum cross slope of 5% or a maximum running slope of 7%.', 'abstract', NULL, 'measurement_primary', 'REF-01002', NULL, 'participatory_spatial', 'mixed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'THE FIGURE THIS PARAMETER HAS LACKED SINCE BATCH 08. An anchoring-tier source stating a MAXIMUM ACCEPTABLE running slope, derived from wheelchair users own perception and Borg-scale perceived effort rather than from a committee -- which is the object GAP-002 names as missing. 7% is ABOVE the 5% specification 8 currently determines, so this evidence LOOSENS the determination rather than confirming it, and that is the honest reading. THE CONDITION IS LOAD-BEARING and is an edge to extraction 44, not prose: 7% holds for a transit distance up to 20 ft and the source says nothing about longer runs -- the same rise-conditioning REF-00996 states as its mechanism. extraction_method SKIM and status PRELIMINARY on purpose: the TRID record and its verbatim abstract were retrieved (HTTP 200, 50825 bytes persisted); THE ARTICLE WAS NOT. Do not promote to verified and do not move this figure into a determination until the full text is read -- participant count, the slope set tested, and whether 7% is the authors recommendation or the highest slope at which perception did not degrade are all unread. The cross-slope figure of 5% in the same sentence is a DIFFERENT PARAMETER and is deliberately not extracted here.', '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (46, 'REF-00979', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'range', '0 to 12', 'degrees', 'Each subject pushed up a wooden ramp (7.3m long) 3 times at self-selected normal and fast speeds for each of these slopes: 0 degrees , 2 degrees , 4 degrees , 6 degrees , 8 degrees , 10 degrees , and 12 degrees .', 'abstract (Design)', NULL, 'measurement_primary', 'REF-00979', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'THE SLOPE SET TESTED -- AN EXPERIMENTAL CONDITION, NOT A CLAIM, and figure_role says so. The CLI help names this exact trap: a tested slope read as a claim is how 1:20, 1:16, 1:12, 1:8 became a range no source ever asserted (extraction_id 1). This row exists so the inflection finding has a row to be conditioned on, and for no other purpose.', '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'condition', 'between');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (47, 'REF-00979', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'range', '4 to 10', 'degrees', 'Major adjustments in stroking kinematics and significant increases in muscle activity occurred at slopes between 4 degrees and 10 degrees .', 'abstract (Results)', NULL, 'measurement_primary', 'REF-00979', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'A DOSE-RESPONSE INFLECTION BAND, NOT A RECOMMENDED RANGE, and the distinction is the whole value of the row. The source locates WHERE the biomechanical burden changes markedly -- between 4 and 10 degrees -- it does not say a ramp should be 4 to 10 degrees. Under the owner statement of 2026-09-16 judgment may reason from effect toward a range AS A PROXY, and this row is the strongest input that reasoning has: unlike the two monotonic curves GAP-002 names (articular discomfort, pushrim force), which resolve degenerately to 0 degrees, this one reports a BAND WITH A LOWER EDGE, which is what a monotonic curve cannot supply. 4 degrees is about 7.0% and arctan-converts to roughly 1:14.3 -- CONVERSION FOR COMPARISON ONLY, per the owner ruling of 2026-09-17; the source wrote degrees and degrees is what this row stores. That 4 degrees lands within a rounding of REF-01002 independently-measured 7% maximum is the batch convergence finding and belongs to synthesis, not here. N=10 young men with paraplegia -- narrow, and the population match row says so.', '2026-09-18 19:58', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:58', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'finding', 'between');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (48, 'REF-00980', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'absent', NULL, NULL, 'Based on these results, changes to the technical requirements for ramp slope and length cannot be recommended at this time.', 'abstract (Conclusion)', NULL, 'measurement_primary', 'REF-00980', NULL, 'instrumented_physical_measurement', 'mixed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'GRADED absent BECAUSE THE CLI WAS RIGHT AND MY FIRST GRADE WAS WRONG. I tried qualitative; add-extraction refused it for want of a claimed_value and named the correct grade -- if the source asserts no value for this parameter that is a RECORDED ABSENCE, which is evidence. It is exactly that: 171 subjects traversed a 30-foot ramp across 1:8 to 1:20 with pulse rate, energy expenditure, rate of travel, distance travelled and rest stops recorded, and the anchoring-tier result is a REFUSAL TO RECOMMEND CHANGING the range tested. This is the OPPOSITE relation to the two insufficient rows batch 15 wrote -- this one CONFIRMS a standard where those found a code inadequate, and it is the corpus first confirms edge against a code. THE LABEL ON THAT EDGE WAS ALSO NARROWED BY A REFUSAL: I first wrote the technical requirements ... under the ADA accessibility guidelines and the verbatim guard rejected it because the conclusion sentence does not contain that phrase -- the ADA framing is in the studys opening sentence, not in the sentence making the claim. THE NAIVE MISREAD IS THE DANGEROUS ONE, named here so the next reader meets it: the companion finding that only a few had difficulty even at 1:8 (12.5%) LOOKS like a warrant for relaxing to 1:8, and the authors explicitly declined to draw it. A 30-foot run at 1:8 is a rise of about 1.14 m and nothing here speaks to a longer ramp. Note too WHAT TRAVERSAL MEASURES -- whether a subject COULD ascend, not whether the slope is acceptable to live with, which is the different question REF-01002 measures by perceived effort.', '2026-09-18 19:58', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 19:58', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'finding', NULL);
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (27, 45, 'condition_on', 44, NULL, NULL, 'named', NULL, 'Results suggest that for a transit distance of up to 20 feet, a ramp should not exceed a maximum cross slope of 5% or a maximum running slope of 7%.', NULL, '2026-09-18 19:57', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (28, 47, 'tested_at', 46, NULL, NULL, 'named', NULL, 'Each subject pushed up a wooden ramp (7.3m long) 3 times at self-selected normal and fast speeds for each of these slopes: 0 degrees , 2 degrees , 4 degrees , 6 degrees , 8 degrees , 10 degrees , and 12 degrees .', NULL, '2026-09-18 19:58', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (29, 48, 'confirms', NULL, 'the technical requirements for ramp slope and length', 'standard', 'named', NULL, 'Based on these results, changes to the technical requirements for ramp slope and length cannot be recommended at this time.', NULL, '2026-09-18 19:58', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors');
